declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/ai.php';release_worker_heartbeat($pdo,'ai','starting','Worker invocation started.');$releaseProcessed=0;$releaseFailed=0;$limit=max(1,min(20,(int)($argv[1]??5)));
for($n=0;$n<$limit;$n++){
 $run=null;$job=job_claim($pdo,'ai_jobs',"SELECT * FROM ai_jobs WHERE status='queued' AND available_at<=NOW() ORDER BY priority ASC,available_at ASC,created_at ASC LIMIT 1",[],1800);if(!$job)break;$id=(int)$job['id'];$token=(string)$job['claim_token'];
 try{$model=(int)($job['model_id']?:0);if(!$model)$model=ai_setting_model_id($pdo,task_route((string)$job['task_type']));if(!$model)throw new RuntimeException('No AI model configured for task.');$user=null;if($job['requested_by_user_id']){$q=$pdo->prepare('SELECT id,public_id,username,display_name,email,role FROM users WHERE id=?');$q->execute([$job['requested_by_user_id']]);$user=$q->fetch()?:null;}[$system,$prompt,$refs,$scopeType,$scopePublic]=build_task($pdo,$job);$initiated=$user?(($user['role']??'')==='admin'?'admin':'pro'):'system';job_claim_renew($pdo,'ai_jobs',$id,$token,1800);$run=ai_run($pdo,$config,$user,$initiated,(string)$job['task_type'],$model,$system,$prompt,$refs,$scopeType,$scopePublic);job_claim_complete($pdo,'ai_jobs',$id,$token);$releaseProcessed++;echo "ai job {$job['id']} done\n";}catch(LostJobClaim $e){if($run&&isset($run['public_id'])){$q=$pdo->prepare("UPDATE ai_runs SET status='failed',error_text='Discarded because worker lease expired before commit.',completed_at=NOW() WHERE public_id=?");$q->execute([$run['public_id']]);}$releaseFailed++;fwrite(STDERR,"ai job {$job['id']}: lease lost; stale result discarded\n");}catch(Throwable $e){try{job_claim_retry_or_fail($pdo,'ai_jobs',$id,$token,substr($e->getMessage(),0,1000),(int)$job['attempts'],3,120);}catch(LostJobClaim $lost){}$releaseFailed++;fwrite(STDERR,"ai job {$job['id']}: {$e->getMessage()}\n");}
