function task_route(string $t): string {return match(true){str_starts_with($t,'moderation_')=>'moderation',$t==='source_change_summary'=>'source_monitor',str_starts_with($t,'research_')=>'research',$t==='transcript_cleanup'=>'transcript_cleanup',default=>'admin'};}
function build_task(PDO $pdo,array $job): array {
 $type=(string)$job['task_type'];$obj=(string)$job['object_public_id'];
 if($type==='source_change_summary'){$id=(int)$obj;$q=$pdo->prepare('SELECT e.*,s.public_id source_public_id,s.title,s.canonical_url,p.extracted_text old_text,n.extracted_text new_text FROM source_change_events e JOIN sources s ON s.id=e.source_id LEFT JOIN source_versions p ON p.id=e.previous_version_id JOIN source_versions n ON n.id=e.new_version_id WHERE e.id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)throw new RuntimeException('Source change event missing.');$system='You are Annotated source-integrity intelligence. Summarize only observable changes. Do not infer motives or truth. Flag whether research evidence may need human review.';$prompt="Source: {$r['title']}\nURL: {$r['canonical_url']}\nDeterministic change type: {$r['change_type']}\nTarget changed: {$r['target_changed']}\nExisting diff summary: {$r['diff_summary']}\n\nPREVIOUS VERSION:\n".mb_substr((string)$r['old_text'],0,14000)."\n\nCURRENT VERSION:\n".mb_substr((string)$r['new_text'],0,14000)."\n\nReturn: concise change summary; likely affected evidence; recommended human review steps.";return [$system,$prompt,[['type'=>'source','id'=>$r['source_public_id']],['type'=>'source_change_event','id'=>$obj]],'source',$r['source_public_id']];}
 if($type==='moderation_rights_triage'){$q=$pdo->prepare('SELECT rc.public_id,rc.claim_type,rc.description,a.public_id annotation_public_id,a.text_commentary,c.selected_text,s.canonical_url FROM rights_claims rc JOIN annotations a ON a.id=rc.annotation_id JOIN captures c ON c.id=a.capture_id JOIN sources s ON s.id=a.source_id WHERE rc.public_id=?');$q->execute([$obj]);$r=$q->fetch();if(!$r)throw new RuntimeException('Rights claim missing.');$system='You assist a human moderation team with triage. Do not make legal conclusions. Do not decide fair use, copyright ownership, privacy liability, or whether content must be removed. Summarize the concern, identify missing facts, and suggest neutral review steps.';$prompt="Claim type: {$r['claim_type']}\nClaim description (claimant identity removed): {$r['description']}\nAnnotation commentary: {$r['text_commentary']}\nCaptured material: ".mb_substr((string)$r['selected_text'],0,6000)."\nOriginal source: {$r['canonical_url']}\n\nProduce a neutral triage memo for a human administrator.";return [$system,$prompt,[['type'=>'rights_claim','id'=>$obj],['type'=>'annotation','id'=>$r['annotation_public_id']]],'rights_claim',$obj];}
 if($type==='moderation_report_triage'){$q=$pdo->prepare('SELECT * FROM moderation_reports WHERE public_id=?');$q->execute([$obj]);$r=$q->fetch();if(!$r)throw new RuntimeException('Moderation report missing.');$system='You assist a human content moderation team. Your output is advisory. Do not take action or make final policy determinations. Summarize the report and suggest what evidence a moderator should inspect.';$prompt="Object type: {$r['object_type']}\nObject id: {$r['object_public_id']}\nReason: {$r['reason']}\nDescription: {$r['description']}\n\nReturn a short triage memo.";return [$system,$prompt,[['type'=>'moderation_report','id'=>$obj]],'moderation_report',$obj];}
 if($type==='research_project_summary'){$q=$pdo->prepare('SELECT * FROM research_projects WHERE public_id=?');$q->execute([$obj]);$p=$q->fetch();if(!$p)throw new RuntimeException('Research project missing.');$ctx=ai_research_context($pdo,(int)$p['id']);$system='You are Annotated research intelligence. Work only from the provided provenance-backed context. Distinguish evidence from inference. Cite source and annotation IDs exactly in square brackets. State when evidence is insufficient.';$prompt="Project: {$p['title']}\nQuestion: Summarize the project, key evidence, disagreements, stale/changed source risks, and next research actions.\n\nCONTEXT:\n".$ctx['text'];return [$system,$prompt,$ctx['refs'],'research_project',$obj];}
 throw new RuntimeException('Unsupported AI job type: '.$type);
}
